app.json:
{
  "budget": {
    "per_run": 0.10
  },
  "capabilities": {
    "records": {
      "account": "rw",
      "contact": "rw",
      "note": "rw",
      "renewal": "rw",
      "ticket": "rw",
      "usage": "rw"
    },
    "connectors": {
      "gmail": {
        "as": "me",
        "can": [
          "read",
          "search",
          "send"
        ],
        "approve": [
          "send"
        ]
      }
    }
  },
  "commands": [
    {
      "id": "renewal-note",
      "label": "Approve CRM note",
      "for": "renewal",
      "run": "renewal-note",
      "params": {
        "renewal": "$record.id"
      }
    },
    {
      "id": "gmail-draft",
      "label": "Draft Gmail to contact",
      "for": "renewal",
      "run": "gmail-draft",
      "params": {
        "renewal": "$record.id"
      }
    },
    {
      "id": "qbr-outline",
      "label": "Make QBR outline",
      "for": "renewal",
      "run": "qbr-outline",
      "params": {
        "renewal": "$record.id"
      }
    }
  ],
  "id": "01M8DDCAT3S0G87PH07DW7Q0YP",
  "kit": 2,
  "name": "Renewal Desk",
  "outputs": {
    "renewals-digest": {
      "label": "Weekly renewals digest",
      "format": "txt",
      "query": {
        "type": "renewal",
        "select": [
          "name",
          "account",
          "stage",
          "renewal_date",
          "value",
          "risk"
        ],
        "window": {
          "order_by": [
            "renewal_date"
          ],
          "limit": 50
        }
      },
      "body": "Renewals due soon, ranked by date. Review every High-risk renewal and confirm the next step with the account owner."
    }
  },
  "records": {
    "account": {
      "common": "organization",
      "fields": {
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "health": {
          "type": "enum",
          "values": [
            "Healthy",
            "Watch",
            "At risk"
          ],
          "default": "Healthy"
        },
        "health_score": {
          "type": "number"
        }
      },
      "present": {
        "title": "name",
        "trailing": "health_score"
      },
      "title": "name"
    },
    "contact": {
      "common": "person",
      "fields": {
        "name": {
          "type": "text",
          "required": true
        },
        "email": {
          "type": "email"
        },
        "account": {
          "type": "ref",
          "to": "account"
        }
      },
      "present": {
        "title": "name",
        "meta": [
          "account"
        ]
      },
      "title": "name"
    },
    "note": {
      "fields": {
        "title": {
          "type": "text",
          "required": true
        },
        "account": {
          "type": "ref",
          "to": "account"
        },
        "renewal": {
          "type": "ref",
          "to": "renewal"
        },
        "body": {
          "type": "longtext"
        },
        "author": {
          "type": "text"
        }
      },
      "present": {
        "title": "title",
        "meta": [
          "account",
          "renewal"
        ]
      },
      "title": "title"
    },
    "renewal": {
      "fields": {
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "account": {
          "type": "ref",
          "to": "account",
          "required": true
        },
        "contact": {
          "type": "ref",
          "to": "contact"
        },
        "stage": {
          "type": "enum",
          "values": [
            "Upcoming",
            "In negotiation",
            "Committed",
            "Won",
            "Lost"
          ],
          "required": true,
          "default": "Upcoming"
        },
        "renewal_date": {
          "type": "date"
        },
        "value": {
          "type": "money",
          "currency": "USD"
        },
        "risk": {
          "type": "enum",
          "values": [
            "Low",
            "Medium",
            "High"
          ]
        },
        "summary": {
          "type": "longtext"
        }
      },
      "present": {
        "title": "name",
        "meta": [
          "account",
          "renewal_date"
        ],
        "trailing": "value",
        "state": "stage",
        "avatar": "contact",
        "money": "value"
      },
      "title": "name"
    },
    "ticket": {
      "fields": {
        "subject": {
          "type": "text",
          "required": true
        },
        "account": {
          "type": "ref",
          "to": "account",
          "required": true
        },
        "status": {
          "type": "enum",
          "values": [
            "Open",
            "Pending",
            "Solved",
            "Closed"
          ],
          "default": "Open"
        },
        "priority": {
          "type": "enum",
          "values": [
            "Low",
            "Normal",
            "High",
            "Urgent"
          ],
          "default": "Normal"
        },
        "opened_at": {
          "type": "date"
        },
        "detail": {
          "type": "longtext"
        }
      },
      "present": {
        "title": "subject",
        "meta": [
          "account",
          "opened_at"
        ],
        "trailing": "status",
        "state": "status"
      },
      "title": "subject"
    },
    "usage": {
      "fields": {
        "name": {
          "type": "text",
          "required": true
        },
        "account": {
          "type": "ref",
          "to": "account",
          "required": true
        },
        "period": {
          "type": "text"
        },
        "active_users": {
          "type": "number"
        },
        "usage_hours": {
          "type": "number"
        },
        "adoption_pct": {
          "type": "number"
        }
      },
      "present": {
        "title": "name",
        "meta": [
          "account"
        ]
      },
      "title": "name"
    }
  },
  "triggers": [
    {
      "id": "weekly-digest",
      "on": "schedule",
      "cron": "0 8 * * 1",
      "run": "weekly-digest"
    }
  ],
  "version": 1
}
